// Wejście: n k. Wypisuje modulo 10^9+7: n!, n!/(n-k)!, n^k, C(n,k), C(n+k-1,k), Catalan(n), D(n).
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;
const int MAXN = 2'000'001;                  // potrzebujemy silni do 2n (Catalan) i n+k-1
long long fact[MAXN], inv_fact[MAXN];

long long power(long long b, long long e) {
    b %= MOD;
    long long r = 1;
    while (e > 0) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
    return r;
}
void init() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = fact[i - 1] * i % MOD;
    inv_fact[MAXN - 1] = power(fact[MAXN - 1], MOD - 2);        // małe twierdzenie Fermata
    for (int i = MAXN - 1; i > 0; i--) inv_fact[i - 1] = inv_fact[i] * i % MOD;
}
long long C(int n, int k) {
    if (n < 0 || k < 0 || k > n) return 0;
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
}

int main() {
    init();
    int n, k;
    cin >> n >> k;                                   // 0 <= k <= n <= 10^6
    cout << fact[n] << "\n";                         // permutacje
    cout << fact[n] * inv_fact[n - k] % MOD << "\n"; // wariacje bez powtórzeń
    cout << power(n, k) << "\n";                     // wariacje z powtórzeniami
    cout << C(n, k) << "\n";                         // kombinacje
    cout << C(n + k - 1, k) << "\n";                 // kombinacje z powtórzeniami
    cout << C(2 * n, n) * power(n + 1, MOD - 2) % MOD << "\n";   // liczba Catalana
    long long d0 = 1, d1 = 0;                        // D(0), D(1)
    for (int i = 2; i <= n; i++) { long long d2 = (i - 1) * ((d0 + d1) % MOD) % MOD; d0 = d1; d1 = d2; }
    cout << (n == 0 ? 1 : d1) << "\n";               // nieporządki
}

