#include <bits/stdc++.h>
using namespace std;

int main() {
    long long N;
    int k;
    cin >> N >> k;
    vector<long long> a(k);
    for (auto &x : a) cin >> x;

    long long total = 0;
    for (int mask = 1; mask < (1 << k); mask++) {
        long long l = 1;                    // NWW liczb z maski
        bool tooBig = false;
        for (int i = 0; i < k && !tooBig; i++)
            if (mask >> i & 1) {
                long long g = __gcd(l, a[i]);
                __int128 nl = (__int128)(l / g) * a[i];   // bez przepełnienia
                if (nl > N) tooBig = true;                // wtedy N / NWW = 0
                else l = (long long)nl;
            }
        if (tooBig) continue;
        long long cnt = N / l;              // ile wielokrotności NWW w [1, N]
        if (__builtin_popcount(mask) % 2 == 1) total += cnt;   // nieparzysta liczba zbiorów: +
        else total -= cnt;                                     // parzysta: -
    }
    cout << total << "\n";
}

