const long long MOD = 1'000'000'007;

long long power(long long b, long long e) {
    long long r = 1; b %= MOD;
    while (e > 0) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
    return r;
}

int main() {
    int n;
    cin >> n;
    vector<double> E(n + 7, 0.0);
    vector<long long> Em(n + 7, 0);
    long long inv6 = power(6, MOD - 2);
    for (int s = n - 1; s >= 0; s--) {               // od stanów końcowych do startu
        double acc = 0; long long accm = 0;
        for (int d = 1; d <= 6; d++) { acc += E[s + d]; accm = (accm + Em[s + d]) % MOD; }
        E[s] = 1 + acc / 6;
        Em[s] = (1 + accm * inv6) % MOD;
    }
    cout << fixed << setprecision(6) << E[0] << "\n" << Em[0] << "\n";
}

