#include <bits/stdc++.h>
using namespace std;
using Big = vector<int>;                       // cyfry od najmłodszej

Big fromString(const string &s) {
    Big a;
    for (int i = (int)s.size() - 1; i >= 0; i--) a.push_back(s[i] - '0');
    while (a.size() > 1 && a.back() == 0) a.pop_back();   // zera wiodące
    return a;
}
string toString(const Big &a) {
    string s;
    for (int i = (int)a.size() - 1; i >= 0; i--) s += char('0' + a[i]);
    return s;
}
Big add(const Big &a, const Big &b) {
    Big c;
    int carry = 0;
    for (size_t i = 0; i < max(a.size(), b.size()) || carry; i++) {
        int s = carry + (i < a.size() ? a[i] : 0) + (i < b.size() ? b[i] : 0);
        c.push_back(s % 10);
        carry = s / 10;
    }
    return c;
}
Big mul(const Big &a, const Big &b) {
    vector<long long> c(a.size() + b.size(), 0);
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = 0; j < b.size(); j++) c[i + j] += (long long)a[i] * b[j];
    Big r;
    long long carry = 0;
    for (size_t i = 0; i < c.size(); i++) {
        long long s = c[i] + carry;
        r.push_back(s % 10);
        carry = s / 10;
    }
    while (carry) { r.push_back(carry % 10); carry /= 10; }
    while (r.size() > 1 && r.back() == 0) r.pop_back();
    return r;
}
int cmp(const Big &a, const Big &b) {          // -1: a<b, 0: równe, 1: a>b
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    for (int i = (int)a.size() - 1; i >= 0; i--)
        if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    return 0;
}

int main() {
    string s, t;
    cin >> s >> t;
    Big a = fromString(s), b = fromString(t);
    cout << toString(add(a, b)) << "\n" << toString(mul(a, b)) << "\n" << cmp(a, b) << "\n";
}

